// Gate test G1: the files under fixtures/ are exactly those in fixtures/MANIFEST.sha256,
// with the listed hashes. Do not edit this file or anything under fixtures/.
import { expect, test } from 'vitest';
import { createHash } from 'node:crypto';
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join, relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('../../', import.meta.url));

function walk(dir: string): string[] {
  return readdirSync(dir).flatMap((name) => {
    const p = join(dir, name);
    return statSync(p).isDirectory() ? walk(p) : [p];
  });
}

test('G1 every fixture file matches the manifest, and no file is missing or extra', () => {
  const listed = new Map<string, string>();
  for (const line of readFileSync(join(ROOT, 'fixtures/MANIFEST.sha256'), 'utf8').split('\n')) {
    if (!line.trim()) continue;
    const [hash, path] = line.split('  ');
    listed.set(path, hash);
  }
  const present = walk(join(ROOT, 'fixtures'))
    .map((p) => relative(ROOT, p).split(sep).join('/'))
    .filter((p) => p !== 'fixtures/MANIFEST.sha256' && !p.includes('__pycache__'))
    .sort();
  expect(present).toEqual([...listed.keys()].sort());
  for (const path of present) {
    const hash = createHash('sha256').update(readFileSync(join(ROOT, path))).digest('hex');
    expect(hash, path).toBe(listed.get(path));
  }
});
